const customers = await api.get('/customers', { status: 'delayed' });
const mails = await api.get('/mails', { label: 'complaint' });
// Assume response data is in .data array
const custIds = new Set(customers.data.map(c => c.id));
const result = mails.data
  .filter(m => custIds.has(m.customer_id))
  .map(m => m.customer_id);
// Deduplicate
const unique = [...new Set(result)];
return {ids: unique};

const customers = await api.get('/customers', { status: 'delayed' });
const mails = await api.get('/mails', { label: 'complaint' });
const delayedIds = new Set(customers.items.map(c => c.id));
const complaintCustomerIds = mails.items.map(m => m.customer_id);
const intersect = [...new Set(complaintCustomerIds.filter(id => delayedIds.has(id)))];
return {ids: intersect};

